def repair_guard_payloads():
    import base64
    expected = {'els_server/storage/fixed_cubes.py', 'els_server/storage/identification_ui.py', 'els_server/storage/seal_quests.py', 'els_server/storage/growth_guide.py', 'els_server/storage/equipment_tuning.py', 'els_server/storage/couple_closures.py', 'els_server/storage/companion_state.py', 'els_server/storage/relationships.py', 'els_server/storage/growth_guide_boxes.py', 'els_server/storage/boosting_2026_essence.py'}
    need(isinstance(REPAIR_RECOVERY_GUARD_PAYLOADS,dict) and set(REPAIR_RECOVERY_GUARD_PAYLOADS)==expected,
         'Exact inherited and Guide recovery guard bindings pending')
    result={}
    for name,row in REPAIR_RECOVERY_GUARD_PAYLOADS.items():
        raw=base64.b64decode(row['base64'],validate=True)
        need(len(raw)==row['size'] and hashlib.sha256(raw).hexdigest()==row['sha256'],'Repair guard byte binding differs')
        result[name]=raw
    return result

